    def rewrite(self, func, **hints):
        """
        Rewrite this object in terms of different functions.

        Examples
        ========

        >>> from sympy import sin, cos, tan, exp, log, sinh, cosh, asin
        >>> from sympy.abc import x, y

        >>> sin(x).rewrite(tan)
        2*tan(x/2)/(tan(x/2)**2 + 1)

        >>> cos(x).rewrite(sin)
        -sin(x + pi/2)

        >>> tan(x).rewrite(sin, cos=True)
        sin(x)/cos(x)

        >>> sinh(log(x))
        x**2/2 - 1/2

        >>> asin(x).rewrite(exp)
        -I*log(I*x + sqrt(1 - x**2))

        """
        from sympy.core.rules import Transform

        # Support rewriting as a different form of the same function.
        if isinstance(func, Basic):
            if self.has(func):
                return self
            elif func.is_Function:
                if isinstance(self, func):
                    return self
                elif func._rewrite_from_func(self, **hints) is not None:
                    return func._rewrite_from_func(self, **hints)
        elif issubclass(func, Basic):
            if isinstance(self, func):
                return self
            elif func._rewrite(self, **hints) is not None:
                return func._rewrite(self, **hints)
        elif isinstance(func, str):
            cls = _sympify(func)
            if cls == self.__class__:
                return self
            if cls._rewrite(self, **hints) is not None:
                return cls._rewrite(self, **hints)

        for rule in self.rewrite_rules:
            if rule.matches(self):
                return rule.rewrite(self, **hints)

        if self.is_Function:
            newargs = [arg.rewrite(func, **hints) for arg in self.args]
            obj = self.__class__(*newargs)
            if obj != self:
                return obj.rewrite(func, **hints)

        return self
